void check(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(1);}}
__global__ void vectorAdd(const float*A,const float*B,float*C,int N){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<N){C[i]=A[i]+B[i];}}
int main(int argc,char**argv){const int N=512,blockSize=128,gridSize=(N+blockSize-1)/blockSize;float a[N],b[N],c[N],*da,*db,*dc;for(int i=0;i<N;++i){a[i]=i%4+1;b[i]=i%4+5;}a[133]=4;b[133]=7;check(cudaMalloc(&da,sizeof(a)));check(cudaMalloc(&db,sizeof(b)));check(cudaMalloc(&dc,sizeof(c)));check(cudaMemcpy(da,a,sizeof(a),cudaMemcpyHostToDevice));check(cudaMemcpy(db,b,sizeof(b),cudaMemcpyHostToDevice));vectorAdd<<<gridSize,blockSize>>>(da,db,dc,N);check(cudaGetLastError());check(cudaMemcpy(c,dc,sizeof(c),cudaMemcpyDeviceToHost));for(int i=0;i<N;++i)if(c[i]!=a[i]+b[i])return 2;cudaFuncAttributes attr;check(cudaFuncGetAttributes(&attr,vectorAdd));if(attr.sharedSizeBytes!=0)return 3;std::ofstream f(argc>1?argv[1]:"cuda_trace.json");f<<"{\"N\":512,\"blockSize\":128,\"gridSize\":4,\"shared_bytes\":"<<attr.sharedSizeBytes<<",\"registers_per_thread\":"<<attr.numRegs<<",\"selected\":{\"block\":1,\"thread\":5,\"warp\":0,\"lane\":5,\"i\":133,\"A\":4,\"B\":7,\"C\":11},\"C\":[";for(int i=0;i<N;++i){if(i)f<<",";f<<c[i];}f<<"],\"measured_mapping_or_cache\":false}";printf("PASS vectorAdd<<<4,128>>> all512; C133=4+7=11; Shared=%zu bytes; %d registers/thread; cache/SM mapping not measured\n",attr.sharedSizeBytes,attr.numRegs);check(cudaFree(da));check(cudaFree(db));check(cudaFree(dc));}
